function valid(s) {
  return s && timeOK(s.time) && Array.isArray(s.held) && s.held.every(r => arrivals.includes(r))
    && new Set(s.held).size === s.held.length && Array.isArray(s.receipts)
    && s.receipts.every(r => r && timeOK(r.time) && Array.isArray(r.qty) && r.qty.length === 3
      && r.qty.every(n => Number.isSafeInteger(n) && n >= 0 && n <= 9999));
