    variance.some(Boolean) ? 'Still expected · '+variance.map((n,i)=>n+' '+items[i].toLowerCase()).filter((_,i)=>variance[i]>0).join(', ') : 'All expected quantities received.';
  "'$('"'historyCount').textContent = '('+state.receipts.length+')';
